def build(symbol: str, out_dir: Path) -> Path:
    """Turn a copied feed response into the parquet layout the engine reads."""
    f = FEED[symbol]
    n = len(SESSIONS) * BARS_PER_SESSION
    for k, v in f.items():
        if len(v) != n:
            raise ValueError(f"{symbol}.{k}: {len(v)} values, expected {n} "
                             f"({len(SESSIONS)} sessions x {BARS_PER_SESSION})")

    ts = [f"{d}T{t}:00Z" for d in SESSIONS for t in BAR_TIMES]
    df = pd.DataFrame({
        "timestamp_utc": pd.to_datetime(ts, utc=True),
        "open": f["open"], "high": f["high"], "low": f["low"], "close": f["close"],
        "volume": 0.0,
    })
    # High must bound open/close and low must be bounded by them, or a transcription slip
    # has shifted one array against another. Cheap check, catches the failure that matters.
    bad = ((df["high"] < df[["open", "close", "low"]].max(axis=1))
           | (df["low"] > df[["open", "close", "high"]].min(axis=1)))
    if bad.any():
        raise ValueError(f"{symbol}: {int(bad.sum())} bars where high/low do not bound "
                         f"open/close; arrays are misaligned")

    df["session_date"] = session_dates(pd.DatetimeIndex(df["timestamp_utc"])).values
    df["symbol"] = symbol
    df["contract_month"] = "209912"
    df["entries_blocked"] = False

    cut = max(SAMPLE_END[symbol], LIQUID_FROM.get(symbol, ""))
    df = df[df["session_date"].astype(str) > cut].reset_index(drop=True)

    out_dir.mkdir(parents=True, exist_ok=True)
    dest = out_dir / f"{symbol}_209912_1min_TRADES.parquet"
    df.to_parquet(dest, index=False)
    return dest


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--out", default="data_oos")
    ap.add_argument("--symbols", nargs="+", default=sorted(FEED))
    args = ap.parse_args(argv)

    print("FRESH BARS, PAST THE IMPORTED SAMPLE END")
    print("=" * 74)
    print("Fetched 2026-08-07. Nothing was fitted to these sessions.")
    print("~17 sessions per symbol: enough to detect a dead strategy, not enough to")
    print("confirm a live one. Read a positive as 'not dead', nothing more.")
    print()
    for sym in args.symbols:
        dest = build(sym, Path(args.out))
        got = pd.read_parquet(dest)
        print(f"  {sym:<5}{len(got):>6} bars  {got['session_date'].nunique():>3} unseen "
              f"sessions  {got['session_date'].min()} to {got['session_date'].max()}  "
              f"(sample ended {SAMPLE_END[sym]})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
